    if threshold >= 30:
        return A
    else:
        k = 0
        while k < m:
            A.remove(k)
            k += 1
        merge_sort(A)
        return A

def calculate_median(A: List[int]) -> int:
    n = len(A)
    if n % 2 == 0:
        median = (A[n // 2] + A[n // 2 - 1]) / 2
    else:
        median = A[(n - 1) // 2]
    return int(median)


def median_nb(A, m):
    sum_t = 0
    count = 0
    if m == 0:
        count = count + 1
    for x in A:
        if x > m:
            count = count + 1
    for x in A:
        if x > m:
